using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddSingleton<ResearchTools>();

builder.Services.AddChatClient(pipeline => pipeline
    .UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<IAgent>(sp =>
{
    var chatClient = sp.GetRequiredService<IChatClient>();
    var tools = sp.GetRequiredService<ResearchTools>();

    return new ChatClientAgent(
        chatClient,
        "ResearchAgent",
        """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using different search queries.
        2. Taking notes on key findings using the note-taking tool.
        3. After gathering enough information (at least 3 searches), produce a final
           summary by reading back your notes and synthesizing them.

        Always take notes on important findings before moving on to the next search.
        When you have enough information, present a well-structured summary.
        """,
        [.. AIFunctionFactory.Create(tools.SearchWeb, tools),
         .. AIFunctionFactory.Create(tools.TakeNote, tools),
         .. AIFunctionFactory.Create(tools.ReadNotes, tools)]);
});

using var host = builder.Build();

var agent = host.Services.GetRequiredService<IAgent>();
var logger = host.Services.GetRequiredService<ILogger<Program>>();

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

try
{
    await foreach (var message in agent.InvokeStreamingAsync(history, options))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }

        logger.LogDebug("Agent step: Role={Role}, ContentLength={Length}",
            message.Role, message.Text?.Length ?? 0);
    }

    Console.WriteLine();
}
catch (Exception ex)
{
    logger.LogError(ex, "Agent execution failed");
    Console.WriteLine($"\nError: {ex.Message}");
}

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools : IDisposable
{
    private readonly HttpClient _httpClient = new();
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns a list of search result titles and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1&no_html=1";

            var response = await _httpClient.GetFromJsonAsync<JsonElement>(url, cancellationToken);

            var results = new List<string>();

            if (response.TryGetProperty("Abstract", out var abstractText)
                && abstractText.GetString() is { Length: > 0 } abs)
            {
                results.Add($"Summary: {abs}");
            }

            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text)
                        && text.GetString() is { Length: > 0 } t)
                    {
                        results.Add($"- {t}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : "No results found. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note taken ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Read back all notes taken so far during the research.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        Console.WriteLine($"  📖 Reading {_notes.Count} note(s)");
        return string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    public void Dispose() => _httpClient.Dispose();
}

