/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools : IDisposable
{
    private readonly HttpClient _httpClient = new();
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns a list of search result titles and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1&no_html=1";

            var response = await _httpClient.GetFromJsonAsync<JsonElement>(url, cancellationToken);

            var results = new List<string>();

            if (response.TryGetProperty("Abstract", out var abstractText)
                && abstractText.GetString() is { Length: > 0 } abs)
            {
                results.Add($"Summary: {abs}");
            }

            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text)
                        && text.GetString() is { Length: > 0 } t)
                    {
                        results.Add($"- {t}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : "No results found. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note taken ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Read back all notes taken so far during the research.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        Console.WriteLine($"  📖 Reading {_notes.Count} note(s)");
        return string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    public void Dispose() => _httpClient.Dispose();
}

